		ctx = templ.ClearChildren(ctx)
		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 5, "<section id=\"agreement\"><h2>2. सम्झौता</h2><p>यी सर्तहरूले तपाईंको सेवाको प्रयोगलाई नियमन गर्छन्। खाता बनाएर, API कुञ्जी बनाएर, वा अन्य तरिकाले सेवा प्रयोग गरेर तपाईं यी सर्तहरूमा सहमत हुनुहुन्छ। यदि तपाईं कम्पनी वा अन्य कानुनी निकायको तर्फबाट स्वीकार गर्दै हुनुहुन्छ भने, तपाईं त्यो निकायलाई बाध्य गराउने अधिकार भएको घोषणा गर्नुहुन्छ, र \"तपाईं\" र \"तपाईंको\" ले त्यो निकायलाई जनाउँछ।</p><p>यदि कुनै विकासकर्ता, साझेदार वा अर्को व्यवसायले तपाईंलाई KIFF चिनायो वा तपाईंले प्रयोग गर्ने एजेन्ट बनायो भने, सेवाका लागि तपाईंको सम्झौता यी सर्तहरूअन्तर्गत सिधै हामीसँग हुन्छ, र तपाईं आफैंले तिनलाई स्वीकार गर्नुहुन्छ। त्यो व्यवसाय हाम्रो एजेन्ट होइन: यसले यी सर्तहरू स्वीकार गर्न, तपाईंको तर्फबाट सहमति दिन वा भुक्तानी स्वीकृत गर्न सक्दैन, र यसले हाम्रो तर्फबाट सेवा बेच्दैन।</p><p>हामी विशेष सुविधाहरू (बिटा सुविधा, तेस्रो पक्षका एकीकरण) का लागि पूरक सर्तहरू प्रकाशित गर्न सक्छौं। जहाँ तिनी यी सर्तहरूसँग बाझिन्छन्, त्यो विशेष सुविधाका लागि पूरक सर्तहरू लागू हुन्छन्।</p></section>")
